// POST body contract: { documents: [{ doc: 'filename-without-extension', text: '# title\n> access_level: all\n\n## section\n...' }] }. The caller supplies repository documents; no undocumented /docs API or filesystem mount is assumed.
const body = $input.first()?.json?.body ?? {};
const documents = Array.isArray(body.documents) ? body.documents : [];
const issues = [];
const validDocs = [];
const accessLevels = new Set();
const chunks = [];
const contactPattern = /(?:\b\d{2,3}[-. ]\d{3,4}[-. ]\d{4}\b|[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i;
for (const entry of documents) {
  const doc = String(entry?.doc ?? '').trim();
  const text = typeof entry?.text === 'string' ? entry.text : '';
  const errors = [];
  if (!doc || !text) errors.push('doc 또는 text가 비어 있음');
  const accessMatch = text.match(/^>\s*access_level:\s*(all|staff)\b/im);
  const sections = [...text.matchAll(/^##\s+(.+)\s*$/gm)];
  if (sections.length < 3) errors.push(`## 절이 3개 미만 (${sections.length})`);
  if (!accessMatch) errors.push('access_level이 없거나 all/staff 값이 아님');
  const pieces = sections.map((match, index) => {
    const start = match.index + match[0].length;
    const end = index + 1 < sections.length ? sections[index + 1].index : text.length;
    return { section: match[1].trim(), text: text.slice(start, end).trim() };
  });
  if (pieces.some(piece => !piece.text)) errors.push('빈 ## 절이 있음');
  if (contactPattern.test(text)) errors.push('연락처 형식 문자열이 포함됨');
  if (errors.length) { issues.push({ doc: doc || null, stage: 'validation', errors }); continue; }
  const access_level = accessMatch[1].toLowerCase();
  accessLevels.add(access_level);
  validDocs.push(doc);
  for (const piece of pieces) chunks.push({ doc, section: piece.section, access_level, text: `# ${doc}\n## ${piece.section}\n${piece.text}`, isChunk: true, status: 'pending' });
}
chunks.sort((a, b) => a.access_level.localeCompare(b.access_level) || a.doc.localeCompare(b.doc) || a.section.localeCompare(b.section));
let lastKey = null;
for (const chunk of chunks) { const key = chunk.access_level; chunk.clearStore = key !== lastKey; lastKey = key; }
const lengths = chunks.map(chunk => chunk.text.length).sort((a, b) => a - b);
const median = lengths.length ? (lengths.length % 2 ? lengths[(lengths.length - 1) / 2] : (lengths[lengths.length / 2 - 1] + lengths[lengths.length / 2]) / 2) : 0;
const stats = { input_document_count: documents.length, valid_document_count: validDocs.length, access_levels: [...accessLevels], chunk_count: chunks.length, chunk_length: { min: lengths[0] ?? 0, median, max: lengths.at(-1) ?? 0 }, issues };
if (chunks.length) return chunks.map(chunk => ({ json: { ...chunk, __stats: stats } }));
return [{ json: { isChunk: false, status: 'no_valid_chunks', __stats: stats } }];
